tasks.solution:
class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, money):
        self.balance += money

    def withdraw(self, money):
        if money > self.balance:
            return False
        self.balance -= money
        return True

    def __str__(self):
        return f"{self.owner}: {self.balance} руб."

