tasks.solution:
class Order:
    def __init__(self, num, total):
        self.num = num
        self.total = total

    def to_pay(self):
        if self.total < 1000:
            return self.total + 200
        return self.total


n = int(input())
orders = []
for _ in range(n):
    num, amount = input().split(",")
    orders.append(Order(num, int(amount)))

grand = 0
for o in orders:
    pay = o.to_pay()
    grand += pay
    print(f"Заказ {o.num}: {pay} руб.")
print(f"Всего к оплате: {grand} руб.")

